export type TokenPath = keyof typeof cssVars;

/** `var(--rd-…)` reference for a token path. Prefer this over hand-written custom properties. */
export function cssVar<P extends TokenPath>(path: P): (typeof cssVars)[P] {
  return cssVars[path];
}
